from typing import List

def maxProduct(nums: List[int], k: int, limit: int) -> int:
    # The problem states the alternating sum is based on the indices *within* the chosen subsequence.
    # Subsequence [a_1, a_2, a_3, ...] has alternating sum a_1 - a_2 + a_3 - ...
    # This means:
    # - If we add an element to a subsequence of even length, it becomes index 0 (even) relative to the new start?
    #   No, if we build from left to right:
    #   - A subsequence of length 1: [x] -> sum = x. Next element y makes it [x, y] -> sum = x - y.
    #   - A subsequence of length 2: [x, y] -> sum = x - y. Next element z makes it [x, y, z] -> sum = x - y + z.
    # Rule:
    # If current subsequence length is even, next element is added (+).
    # If current subsequence length is odd, next element is subtracted (-).
    # Exception: The very first element of any subsequence is always added (+).

    # dp_odd[sum] = set of products for subsequences with odd length
    # dp_even[sum] = set of products for subsequences with even length
    dp_odd = {}
    dp_even = {}

    for x in nums:
        new_odd = {}
        new_even = {}

        # Case 1: Start a new subsequence with x (length 1, odd)
        if x <= limit:
            new_odd[x] = {x}

        # Case 2: Append x to an existing even-length subsequence
        # New length will be odd. Sum change: old_sum + x
        for s, products in dp_even.items():
            new_s = s + x
            if -1800 <= new_s <= 1800:
                if new_s not in new_odd:
                    new_odd[new_s] = set()
                for p in products:
                    new_p = p * x
                    if new_p <= limit:
                        new_odd[new_s].add(new_p)

        # Case 3: Append x to an existing odd-length subsequence
        # New length will be even. Sum change: old_sum - x
        for s, products in dp_odd.items():
            new_s = s - x
            if -1800 <= new_s <= 1800:
                if new_s not in new_even:
                    new_even[new_s] = set()
                for p in products:
                    new_p = p * x
                    if new_p <= limit:
                        new_even[new_s].add(new_p)

        # Merge updates into DP tables to ensure we don't use the same element twice 
        # for the same transition path in one iteration.
        for s, products in new_odd.items():
            if s not in dp_odd:
                dp_odd[s] = set()
            dp_odd[s].update(products)

        for s, products in new_even.items():
            if s not in dp_even:
                dp_even[s] = set()
            dp_even[s].update(products)

    max_p = -1
    if k in dp_odd:
        for p in dp_odd[k]:
            if p > max_p:
                max_p = p
    if k in dp_even:
        for p in dp_even[k]:
            if p > max_p:
                max_p = p

    return max_p

