from typing import List

def countComponents(nums: List[int], threshold: int) -> int:
    # Use a dictionary to store the parent for DSU.
    # Only numbers in nums are nodes in our graph.
    parent = {x: x for x in nums}

    # Iterative find with path compression to avoid RecursionError.
    def find(i):
        root = i
        while parent[root] != root:
            root = parent[root]
        while parent[i] != root:
            next_node = parent[i]
            parent[i] = root
            i = next_node
        return root

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    # A number x can only have an edge if x <= threshold.
    # If lcm(x, y) <= threshold, then both x and y must be <= threshold.
    exists = set()
    for x in nums:
        if x <= threshold:
            exists.add(x)

    # Property: x and y are connected if there exists some M <= threshold 
    # such that x is a divisor of M and y is a divisor of M.
    # (Because then lcm(x, y) must divide M, so lcm(x, y) <= M <= threshold).

    # To implement this in O(threshold * log(threshold)):
    # For every multiple m from 1 to threshold:
    #   All divisors d of m that are present in `nums` belong to the same component.

    # We use a dictionary 'rep' to store one representative divisor from `exists` for each multiple m.
    rep = {}
    for x in exists:
        # Iterate through all multiples of x up to threshold.
        for m in range(x, threshold + 1, x):
            if m not in rep:
                rep[m] = x
            else:
                union(x, rep[m])

    # The number of connected components is the count of unique roots for all nums.
    roots = set()
    for x in nums:
        roots.add(find(x))
    return len(roots)

