from typing import List

def sortMatrix(grid: List[List[int]]) -> List[List[int]]:
    n = len(grid)
    diagonals = {}

    # Collect elements for each diagonal (r - c is constant)
    for r in range(n):
        for c in range(n):
            k = r - c
            if k not in diagonals:
                diagonals[k] = []
            diagonals[k].append(grid[r][c])

    # Sort based on the requirements:
    # Bottom-left (k >= 0) non-increasing -> reverse=True
    # Top-right (k < 0) non-decreasing -> reverse=False
    for k in diagonals:
        if k >= 0:
            diagonals[k].sort(reverse=True)
        else:
            diagonals[k].sort()

    # Reconstruct the grid
    # Using a pointer dict to track current element for each diagonal k
    ptr = {k: 0 for k in diagonals}
    for r in range(n):
        for c in range(n):
            k = r - c
            grid[r][c] = diagonals[k][ptr[k]]
            ptr[k] += 1

    return grid
