from typing import List

def numberOfComponents(properties: List[List[int]], k: int) -> int:
    n = len(properties)
    # 將每個 list 轉為 set 以便快速計算交集並去重
    sets = [set(p) for p in properties]

    # 使用鄰接表表示圖
    adj = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            # 計算兩個集合的交集數量是否 >= k
            if len(sets[i] & sets[j]) >= k:
                adj[i].append(j)
                adj[j].append(i)

    visited = [False] * n
    components = 0

    # 使用 BFS 或 DFS遍歷所有節點，計算連通分量數量
    for i in range(n):
        if not visited[i]:
            components += 1
            stack = [i]
            visited[i] = True
            while stack:
                u = stack.pop()
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)

    return components
