from typing import List

def numberOfComponents(properties: List[List[int]], k: int) -> int:
    n = len(properties)
    # 將每個 list 轉為 set 以方便計算交集並過濾重複元素
    sets = [set(p) for p in properties]

    # 使用 BFS 或 DFS 來traversal 圖，這裡用簡單的 visited 陣列與鄰接表的概念
    adj = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            # 計算交集的大小
            if len(sets[i] & sets[j]) >= k:
                adj[i].append(j)
                adj[j].append(i)

    visited = [False] * n
    count = 0

    for i in range(n):
        if not visited[i]:
            count += 1
            # BFS 開始探索連通分量
            stack = [i]
            visited[i] = True
            while stack:
                u = stack.pop()
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)

    return count
