import heapq

def is_prime(k):
    if k < 2: return False
    for i in range(2, int(k**0.5) + 1):
        if k % i == 0: return False
    return True

def minOperations(n: int, m: int):
    # The integer n must not be a prime number at any point, including its original value.
    # Also the target m must not be a prime number.
    if is_prime(n) or is_prime(m):
        return -1

    # Dijkstra's algorithm for shortest path in a weighted graph
    # The cost of transformation is the sum of all values n takes throughout operations.
    # If sequence is n -> v1 -> v2 -> ... -> m, total cost is n + v1 + v2 + ... + m.

    pq = [(n, n)]  # (current_total_cost, current_value)
    dist = {n: n}

    while pq:
        d, u = heapq.heappop(pq)

        if u == m:
            return d

        if d > dist.get(u, float('inf')):
            continue

        s_curr = list(str(u))
        for i in range(len(s_curr)):
            digit = int(s_curr[i])

            # Option 1: Increase digit (if not 9)
            if digit < 9:
                new_list = s_curr[:]
                new_list[i] = str(digit + 1)
                v = int("".join(new_list))
                if not is_prime(v):
                    new_dist = d + v
                    if new_dist < dist.get(v, float('inf')):
                        dist[v] = new_dist
                        heapq.heappush(pq, (new_dist, v))

            # Option 2: Decrease digit (if not 0)
            if digit > 0:
                new_list = s_curr[:]
                new_list[i] = str(digit - 1)
                v = int("".join(new_list))
                if not is_prime(v):
                    new_dist = d + v
                    if new_dist < dist.get(v, float('inf')):
                        dist[v] = new_dist
                        heapq.heappush(pq, (new_dist, v))

    return -1
```

這是一個典型的最短路徑問題，可以使用 **Dijkstra 演算法** 來解決。我們將每個數字視為圖中的節點，邊的權重是轉變後數值的總和。

```python
import heapq

def minOperations(n: int, m: int):
    # 如果目標 m 是質數，根據題目要求無法達成
    def is_prime(k):
        if k < 2: return False
        for i in range(2, int(k**0.5) + 1):
            if k % i == 0: return False
        return True

    if is_prime(m):
        return -1

    # 如果初始 n 是質數，也無法開始
    if is_prime(n):
        return -1

    # Dijkstra 初始化
    # distance[x] 儲存從 n 到 x 的最小成本
    # 注意：成本是路徑上所有經過的數值總和
    dist = {}
    pq = [(0, n)]  # (current_cost, current_value)
    dist[n] = n     # 起點成本為初始值 n

    while pq:
        d, curr = heapq.heappop(pq)

        if curr == m:
            return d

        if d > dist.get(curr, float('inf')):
            continue

        s_curr = str(curr)
        for i in range(len(s_curr)):
            digit = int(s_curr[i])

            # 嘗試增加或減少數值
            for delta in [1, -1]:
                new_digit = digit + delta
                if 0 <= new_digit <= 9:
                    # 確保不改變數字長度 (例如 10 變成 09 不允許，但題目說 digits 相同)
                    # 這裡主要檢查新數值是否合法且不是質數
                    new_val = int(s_curr[:i] + str(new_digit) + s_curr[i+1:])

                    if len(str(new_val)) == len(s_curr) and not is_prime(new_val):
                        new_dist = d + new_val
                        if new_dist < dist.get(new_val, float('inf')):
                            dist[new_val] = new_dist
                            heapq.heappush(pq, (new_dist, new_val))

    return -1
```

