from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    # online_until[user_id] stores the timestamp when the user will be back online
    online_until = [float('inf')] * numberOfUsers

    # Sort events by timestamp to ensure chronological processing.
    # If timestamps are equal, OFFLINE must come before MESSAGE (as per instructions).
    # We can use a tuple for sorting: (timestamp, type_priority)
    # Let's assign priority 0 to OFFLINE and 1 to MESSAGE.
    sorted_events = []
    for e in events:
        type_prio = 0 if e[0] == "OFFLINE" else 1
        sorted_events.append((int(e[1]), type_prio, e))

    # Sort by timestamp first, then by priority
    sorted_events.sort()

    for _, _, event in sorted_events:
        etype = event[0]
        if etype == "OFFLINE":
            uid = int(event[2].replace("id", ""))
            online_until[uid] = int(event[1]) + 60
        else:
            content = event[2]
            if content == "ALL":
                for i in range(numberOfUsers):
                    mentions[i] += 1
            elif content == "HERE":
                for i in range(numberOfUsers):
                    if online_until[i] > int(event[1]):
                        mentions[i] += 1
            else:
                tokens = content.split()
                for token in tokens:
                    if token.startswith("id"):
                        uid = int(token[2:])
                        mentions[uid] += 1

    return mentions
