                # Option 1: Don't neutralize current cell
                prev_max = -float('inf')
                if i > 0: prev_max = max(prev_max, dp[k][i-1][j])
                if j > 0: prev_max = max(prev_max, dp[k][i][j-1])

                if prev_max != -float('inf'):
