from typing import List

def countPathsWithXorValue(grid: List[List[int]], k: int) -> int:
    m, n = len(grid), len(grid[0])
    MOD = 10**9 + 7
    # dp[i][j] is a list/dict of {xor_sum: count}
    # Given grid values < 16 and k < 16, xor sum is always < 16.
    # Use a 3D array for speed: dp[row][col][xor_val]
    dp = [[[0] * 16 for _ in range(n)] for _ in range(m)]

    dp[0][0][grid[0][0]] = 1

    for i in range(m):
        for j in range(n):
            for x in range(16):
                if dp[i][j][x] == 0: continue
                count = dp[i][j][x]
                # Move Down
                if i + 1 < m:
                    dp[i+1][j][x ^ grid[i+1][j]] = (dp[i+1][j][x ^ grid[i+1][j]] + count) % MOD
                # Move Right
                if j + 1 < n:
                    dp[i][j+1][x ^ grid[i][j+1]] = (dp[i][j+1][x ^ grid[i][j+1]] + count) % MOD

    return dp[m-1][n-1][k]
