from typing import List

def assignElements(groups: List[int], elements: List[int]) -> List[int]:
    # 建立一個映射表：數值 -> 最小的索引
    # 因為題目要求選擇最小索引，我們只記錄第一次出現的元素
    min_idx = {}
    for i, val in enumerate(elements):
        if val not in min_idx:
            min_idx[val] = i

    # 預處理：找出每個數值對應的所有「因數」中，最小索引是誰
    # 因為 groups[i] 必須能被 elements[j] 整除，即 elements[j] 是 groups[i] 的因數。
    # 我們可以用一個陣列來存儲每個數字對應的最小元素索引
    max_val = max(groups) if groups else 0
    best_element_idx = [-1] * (max_val + 1)

    # 先把所有可用的 elements 填入對應的數值位置（若重複則保留最小 index）
    for val, idx in min_idx.items():
        if val <= max_val:
            best_element_idx[val] = idx

    # 使用類似篩法的邏輯，找出每個數字的所有因數中，最小的索引
    # 但題目要求是「groups[i] 能被 elements[j] 整除」，這意味著 elements[j] 是 groups[i] 的約數。
    # 所以我們只需要檢查 groups[i] 的所有約數。

    res = []
    for g in groups:
        best_idx = -1
        # 找出 g 的所有約數，並從 min_idx 中找最小的 index
        # 為了效率，直接遍歷到 sqrt(g)
        for i in range(1, int(g**0.5) + 1):
            if g % i == 0:
                # i 是約數
                if i in min_idx:
                    if best_idx == -1 or min_idx[i] < best_idx:
                        best_idx = min_idx[i]
                # g // i 也是約數
                other = g // i
                if other in min_idx:
                    if best_idx == -1 or min_idx[other] < best_idx:
