def assignElements(groups: List[int], elements: List[int]) -> List[int]:
    limit = 0
    for x in groups:
        if x > limit: limit = x
    for x in elements:
        if x > limit: limit = x

    min_idx = [-1] * (limit + 1)
    for i, v in enumerate(elements):
        if min_idx[v] == -1:
            min_idx[v] = i

    res = []
