        best_j = float('inf')
        # Standard divisor finding is O(sqrt(N))
        for d in range(1, int(g**0.5) + 1):
            if g % d == 0:
                d1 = d
                d2 = g // d
                idx1 = min_idx[d1] if d1 <= limit else -1
                idx2 = min_idx[d2] if d2 <= limit else -1
                if idx1 != -1: best_j = min(best_j, idx1)
                if idx2 != -1: best_j = min(best_j, idx2)
        res.append(best_j if best_j != float('inf') else -1)
