from typing import List

def minCost(n: int, cost: List[List[int]]) -> int:
    half = n // 2
    # dp[c1][c2] is the min cost for house i and n-1-i having colors c1 and c2
    dp = [[float('inf')] * 3 for _ in range(3)]

    # Base case: first pair (0, n-1)
    for c1 in range(3):
        for c2 in range(3):
            if c1 != c2:
                dp[c1][c2] = cost[0][c1] + cost[n-1][c2]

    # Transition for pairs from 1 to half - 1
    for i in range(1, half):
        new_dp = [[float('inf')] * 3 for _ in range(3)]
        for c1 in range(3): # color of house i
            for c2 in range(3): # color of house n-1-i
                if c1 == c2:
                    continue

                best_prev = float('inf')
                # Check previous pair (i-1, n-i)
                for pc1 in range(3): # color of house i-1
                    for pc2 in range(3): # color of house n-i
                        if c1 != pc1 and c2 != pc2:
                            if dp[pc1][pc2] < best_prev:
                                best_prev = dp[pc1][pc2]

                if best_prev != float('inf'):
                    new_dp[c1][c2] = best_prev + cost[i][c1] + cost[n-1-i][c2]
        dp = new_dp

    res = float('inf')
    for row in dp:
        res = min(res, min(row))
    return int(res)
