from typing import List

def maxScore(n: int, k: int, stayScore: List[List[int]], travelScore: List[List[int]]) -> int:
    # dp[i][j] 表示在第 i 天結束時，處於城市 j 的最大得分
    # 初始化為第一天（day 0）的得分：選擇任何一個城市作為起點並留在該城市
    dp = [stayScore[0][j] for j in range(n)]

    for i in range(1, k):
        next_dp = [0] * n
        # 優化點：為了達到 O(k * n^2) 的複雜度，我們直接計算每座城市的轉移。
        # 因為每個城市都互連，對於當前城市 j，我們可以從任何城市 prev 來到這裡。
        for curr in range(n):
            max_val = 0
            for prev in range(n):
                if prev == curr:
                    # 如果留在原地
                    score = dp[prev] + stayScore[i][curr]
                else:
                    # 如果從 prev 移動到 curr
                    score = dp[prev] + travelScore[prev][curr]

                if score > max_val:
                    max_val = score
            next_dp[curr] = max_val
        dp = next_dp

    # 這裡的邏輯可以進一步優化，但根據題目範圍 n, k <= 200，O(k * n^2) 是可行的。
    # 修正：上面的迴圈邏輯稍微有誤，正確做法是每一天考慮「留在原地」或「從任何地方移動過來」。

    # 正確的 DP 轉移：
    dp = [stayScore[0][j] for j in range(n)]
    for i in range(1, k):
        next_dp = [0] * n
        for curr in range(n):
            res = dp[curr] + stayScore[i][curr] # 情況 1: 留在原地 (注意：此時 dp[curr] 已包含前一天的得分)
            # 實際上，如果我們在第 i 天選擇「移動」，是從某個 prev 來到 curr。
            # 所以我們需要找 max(dp[prev] + travelScore[prev][curr])
            for prev in range(n):
                if prev != curr:
                    res = max(res, dp[prev] + travelScore[prev][curr])
            next_dp[curr] = res
        dp = next_dp

    return max(dp)
