from typing import List

def getLargestOutlier(nums: List[int]) -> int:
    total_sum = sum(nums)
    ans = float('-inf')

    # The total sum of all elements is (SumOfSpecialNumbers + SumElement + Outlier)
    # Let S = SumOfSpecialNumbers. Then:
    # total_sum = S + S + Outlier  =>  total_sum = 2*S + Outlier
    # Therefore, for any element x in nums, if we assume it is the outlier:
    # S = (total_sum - x) / 2
    # We then need to check if there exists another element y in nums such that y == S.
    # If so, the remaining n-2 elements are special numbers and their sum is S.

    count = {}
    for x in nums:
        count[x] = count.get(x, 0) + 1

    for i in range(len(nums)):
        x = nums[i]
        # Remaining elements sum to (total_sum - x)
        rem_sum = total_sum - x

        if rem_sum % 2 == 0:
            S = rem_sum // 2
            # We need to check if S exists in the remaining elements.
            # If S is different from x, count[S] must be > 0.
            # If S is same as x, count[x] must be > 1 (since one x is outlier).
            if S != x:
                if S in count and count[S] > 0:
                    ans = max(ans, x)
            else:
                if count[x] > 1:
                    ans = max(ans, x)

    return int(ans)
