from typing import List

def maxAmount(initialCurrency: str, pairs1: List[List[str]], rates1: List[float], 
               pairs2: List[List[str]], rates2: List[float]) -> float:
    """
    Calculates the maximum amount of initialCurrency after performing any number 
    of conversions on day 1 and then any number of conversions on day 2.

    Edge cases handled:
    - Empty conversion lists (n=0 or m=0): Handled by loops not executing.
    - Single element/No path to initialCurrency: Returns 1.0 correctly.
    - Multiple paths to same currency: Uses Bellman-Ford style relaxation to ensure maximum rate.
    - Cycle handling: Constraints say no contradictions, but multiple visits are allowed via relaxation.
    """

    # Build adjacency lists for both days
    adj1 = {}
    for i in range(len(pairs1)):
        u, v = pairs1[i]
        r = rates1[i]
        if u not in adj1: adj1[u] = {}
        adj1[u][v] = max(adj1[u].get(v, 0.0), r)

    adj2 = {}
    for i in range(len(pairs2)):
        u, v = pairs2[i]
        r = rates2[i]
        if u not in adj2: adj2[u] = {}
        adj2[u][v] = max(adj2[u].get(v, 0.0), r)

    # Day 1: Calculate maximum amounts for all reachable currencies
    # Using a dictionary to store the best rate found so far for each currency
    amounts1 = {initialCurrency: 1.0}

    # Since n is small (<= 10), we can use a standard relaxation approach 
    # to find maximum path values in a DAG/Graph without cycles.
    # We iterate enough times to propagate the max values through all possible edges.
    for _ in range(len(pairs1) + 1):
        changed = False
        for u, neighbors in adj1.items():
            if u in amounts1:
                for v, r in neighbors.items():
                    new_val = amounts1[u] * r
                    if new_val > amounts1.get(v, 0.0):
                        amounts1[v] = new_val
                        changed = True
        if not changed:
            break

    # Day 2: Starting from all results of Day 1, find maximum amount for initialCurrency
    # We don't need to reset; we just continue the relaxation from current amounts1.
    amounts2 = amounts1.copy()
    for _ in range(len(pairs2) + 1):
        changed = False
        for u, neighbors in adj2.items():
            if u in amounts2:
                for v, r in neighbors.items():
                    new_val = amounts2[u] * r
                    if new_val > amounts2.get(v, 0.0):
                        amounts2[v] = new_val
                        changed = True
        if not changed:
            break

    # The goal is the maximum amount of initialCurrency we can have at the end.
    return float(amounts2.get(initialCurrency, 1.0))
