from collections import defaultdict

def maxAmount(initialCurrency: str, pairs1: List[List[str]], rates1: List[float], 
               pairs2: List[List[str]], rates2: List[float]) -> float:
    # Build adjacency lists for both days
    adj1 = defaultdict(list)
    for (u, v), r in zip(pairs1, rates1):
        adj1[u].append((v, r))
        adj1[v].append((u, 1.0 / r))

    adj2 = defaultdict(list)
    for (u, v), r in zip(pairs2, rates2):
        adj2[u].append((v, r))
        adj2[v].append((u, 1.0 / r))

    # Step 1: Find max amount of each currency reachable on Day 1
    # Using BFS/DFS to find the maximum path (since no cycles are guaranteed)
    max_day1 = defaultdict(float)
    max_day1[initialCurrency] = 1.0

    stack = [initialCurrency]
    while stack:
        u = stack.pop()
        for v, r in adj1[u]:
            if max_day1[v] < max_day1[u] * r:
                max_day1[v] = max_day1[u] * r
                stack.append(v)

    # Step 2: Find max amount of initialCurrency reachable on Day 2 starting from any Day 1 result
    # We can treat all currencies reached on Day 1 as potential starting points for Day 2
    max_day2 = defaultdict(float)
    for curr, amount in max_day1.items():
        if amount > max_day2[curr]:
            max_day2[curr] = amount

    stack = list(max_day2.keys())
    while stack:
        u = stack.pop()
        for v, r in adj2[u]:
            if max_day2[v] < max_day2[u] * r:
                max_day2[v] = max_day2[u] * r
                stack.append(v)

    return max(max_day2.get(initialCurrency, 1.0), 1.0)
