def maxAmount(initialCurrency: str, pairs1: List[List[str]], rates1: List[float], 
               pairs2: List[List[str]], rates2: List[float]) -> float:
    # Build adjacency lists for both days (include reverse edges)
    adj1 = {}
    for i in range(len(pairs1)):
        u, v = pairs1[i]
        r = rates1[i]
        adj1.setdefault(u, {})[v] = max(adj1.get(u, {}).get(v, 0), r)
        adj1.setdefault(v, {})[u] = max(adj1.get(v, {}).get(u, 0), 1/r)

    adj2 = {}
    for i in range(len(pairs2)):
        u, v = pairs2[i]
        r = rates2[i]
        adj2.setdefault(u, {})[v] = max(adj2.get(u, {}).get(v, 0), r)
        adj2.setdefault(v, {})[u] = max(adj2.get(v, {}).get(u, 0), 1/r)

    # BFS to find all reachable values from initialCurrency on Day 1
    dist1 = {initialCurrency: 1.0}
    queue1 = [initialCurrency]
    for u in queue1:
        if u in adj1:
            for v, r in adj1[u].items():
                new_val = dist1[u] * r
                if new_val > dist1.get(v, 0):
                    dist1[v] = new_val
                    queue1.append(v)

    # BFS to find all reachable values from Day 1 results on Day 2
    dist2 = dist1.copy()
    queue2 = list(dist1.keys())
    for u in queue2:
        if u in adj2:
            for v, r in adj2[u].items():
                new_val = dist2[u] * r
                if new_val > dist2.get(v, 0):
                    dist2[v] = new_val
                    queue2.append(v)

    return max(dist2.values()) if dist2 else 1.0
